"use client";

// analytics-exempt
import { Suspense, useState, useEffect, useCallback } from "react";
import { useSearchParams } from "@/lib/nav";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import type Fuse from "fuse.js";
import { loadDocs, buildFuseIndex } from "@/lib/docs/docLoader";
import type { DocEntry } from "@/lib/docs/docLoader";
import * as styles from "./help.css";

export default function HelpPage() {
  // useSearchParams requires a Suspense boundary for static prerendering.
  return (
    <Suspense fallback={null}>
      <HelpPageContent />
    </Suspense>
  );
}

function HelpPageContent() {
  const docParam = useSearchParams()?.get("doc") ?? null;
  const [docs, setDocs] = useState<DocEntry[]>([]);
  const [filteredDocs, setFilteredDocs] = useState<DocEntry[]>([]);
  const [selectedSlug, setSelectedSlug] = useState<string | null>(null);
  const [query, setQuery] = useState("");
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState(false);
  const [reloadTick, setReloadTick] = useState(0);
  const [fuseIndex, setFuseIndex] = useState<Fuse<DocEntry> | null>(null);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setLoadError(false);
    loadDocs()
      .then((entries) => {
        if (cancelled) return;
        const index = buildFuseIndex(entries);
        setDocs(entries);
        setFilteredDocs(entries);
        setFuseIndex(index);
        if (entries.length > 0) {
          const deepLinked = docParam && entries.find((d) => d.slug === docParam);
          setSelectedSlug(deepLinked ? deepLinked.slug : entries[0].slug);
        } else {
          // loadDocs() swallows per-file failures (allSettled), so "nothing loaded" is the failure signal.
          setLoadError(true);
        }
      })
      .catch(() => {
        if (!cancelled) setLoadError(true);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
    // docParam is read once per load; later changes are handled by the effect below.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [reloadTick]);

  useEffect(() => {
    if (docParam && docs.some((d) => d.slug === docParam)) {
      setQuery("");
      setFilteredDocs(docs);
      setSelectedSlug(docParam);
    }
  }, [docParam, docs]);

  const handleSearch = useCallback(
    (value: string) => {
      setQuery(value);
      if (!value.trim() || !fuseIndex) {
        setFilteredDocs(docs);
        return;
      }
      const results = fuseIndex.search(value);
      const matched = results.map((r) => r.item);
      setFilteredDocs(matched);
      if (matched.length > 0 && !matched.find((d) => d.slug === selectedSlug)) {
        setSelectedSlug(matched[0].slug);
      }
    },
    [docs, fuseIndex, selectedSlug]
  );

  const selectedDoc = docs.find((d) => d.slug === selectedSlug) ?? null;

  return (
    <div className={styles.pageRoot} id="main-content">
      {/* Sidebar */}
      <nav className={styles.sidebar} aria-label="Documentation navigation">
        <input
          type="search"
          className={styles.searchInput}
          placeholder="Search docs…"
          value={query}
          onChange={(e) => handleSearch(e.target.value)}
          aria-label="Search documentation"
        />
        {loading ? (
          <div className={styles.loadingContainer}>Loading…</div>
        ) : (
          filteredDocs.map((doc) => (
            <button
              key={doc.slug}
              className={styles.sidebarLink({ active: doc.slug === selectedSlug })}
              onClick={() => setSelectedSlug(doc.slug)}
              aria-current={doc.slug === selectedSlug ? "page" : undefined}
            >
              {doc.title}
            </button>
          ))
        )}
      </nav>

      {/* Article pane */}
      <main className={styles.articlePane}>
        {loading ? (
          <div className={styles.loadingContainer}>Loading documentation…</div>
        ) : loadError ? (
          <div className={styles.loadingContainer} data-testid="help-load-error">
            <p role="alert">Couldn&apos;t load the documentation.</p>
            <button type="button" autoFocus onClick={() => setReloadTick((t) => t + 1)}>Retry</button>
          </div>
        ) : selectedDoc ? (
          <article className={styles.markdownBody}>
            <ReactMarkdown remarkPlugins={[remarkGfm]}>
              {selectedDoc.content}
            </ReactMarkdown>
          </article>
        ) : (
          <div className={styles.loadingContainer}>
            {query ? "No results found." : "Select a topic from the sidebar."}
          </div>
        )}
      </main>
    </div>
  );
}
